files.content:
.gummy-separator {
  --separator-color: color-mix(in oklch, var(--line-strong) 60%, transparent);
  position: relative;
  flex: none;
  overflow: visible;
  background: linear-gradient(90deg, transparent, var(--separator-color) 12% 88%, transparent);
}

.gummy-separator[data-orientation="horizontal"] {
  width: 100%;
  height: 1px;
  margin-block: 20px;
}

.gummy-separator[data-orientation="vertical"] {
  width: 1px;
  height: 100%;
  min-height: 28px;
  margin-inline: 16px;
  background: linear-gradient(transparent, var(--separator-color) 12% 88%, transparent);
}

.gummy-separator__pool {
  position: absolute;
  border: 1px solid color-mix(in oklch, var(--fruit-aqua-rim) 38%, transparent);
  background:
    radial-gradient(circle at 30% 20%, oklch(1 0 0 / 0.72), transparent 20%),
    color-mix(in oklch, var(--fruit-aqua-core) 42%, transparent);
  box-shadow: inset 0 -2px 3px color-mix(in oklch, var(--fruit-aqua-depth) 26%, transparent);
}

.gummy-separator[data-orientation="horizontal"] .gummy-separator__pool {
  right: 8%;
  bottom: -3px;
  width: 34px;
  height: 7px;
  border-radius: 58% 42% 48% 52%;
}

.gummy-separator[data-orientation="vertical"] .gummy-separator__pool {
  right: -3px;
  bottom: 8%;
  width: 7px;
  height: 34px;
  border-radius: 48% 56% 44% 52%;
}

.gummy-separator[data-tone="quiet"] .gummy-separator__pool {
  opacity: 0.52;
  filter: saturate(0.72);
}

.gummy-heading {
  margin: 0;
  color: var(--ink);
  font-family: var(--font-display), ui-sans-serif, system-ui, sans-serif;
  font-weight: 790;
  letter-spacing: -0.045em;
  line-height: 0.98;
}

.gummy-heading[data-balance="true"] {
  text-wrap: balance;
}

.gummy-heading[data-size="display"] { font-size: clamp(3.6rem, 10vw, 8.5rem); letter-spacing: -0.072em; line-height: 0.84; }
.gummy-heading[data-size="title"] { font-size: clamp(2.5rem, 6vw, 5.25rem); line-height: 0.9; }
.gummy-heading[data-size="section"] { font-size: clamp(1.85rem, 3vw, 3.15rem); }
.gummy-heading[data-size="subsection"] { font-size: clamp(1.2rem, 2vw, 1.6rem); letter-spacing: -0.025em; line-height: 1.1; }

.gummy-text {
  margin: 0;
  color: var(--ink);
}

.gummy-text[data-size="small"] { font-size: 0.875rem; line-height: 1.55; }
.gummy-text[data-size="large"] { font-size: clamp(1.075rem, 1.5vw, 1.25rem); line-height: 1.6; }
.gummy-text[data-tone="soft"] { color: var(--ink-soft); }
.gummy-text[data-tone="muted"] { color: var(--muted); }
.gummy-text[data-measure="compact"] { max-width: 42ch; }
.gummy-text[data-measure="reading"] { max-width: 68ch; }
.gummy-text[data-measure="wide"] { max-width: 82ch; }
.gummy-text[data-measure="none"] { max-width: none; }

.gummy-eyebrow {
  margin: 0;
  color: color-mix(in oklch, var(--fruit-raspberry-rim) 78%, var(--ink));
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.72rem;
  font-weight: 760;
  letter-spacing: 0.11em;
  line-height: 1.4;
  text-transform: uppercase;
}

:root[data-theme="dark"] .gummy-eyebrow {
  color: var(--fruit-raspberry-light);
}

.gummy-inline-code {
  padding: 0.16em 0.42em 0.2em;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 28%, var(--line));
  border-radius: 0.52em 0.62em 0.48em 0.58em;
  background: color-mix(in oklch, var(--fruit-grape-light) 18%, var(--surface-solid));
  color: var(--ink);
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.88em;
}

.gummy-blockquote {
  position: relative;
  max-width: 68ch;
  margin: 0;
  padding: 20px 24px 20px 30px;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 24%, var(--line));
  border-radius: 15px 22px 17px 20px;
  background: color-mix(in oklch, var(--surface-solid) 88%, var(--fruit-grape-light));
  box-shadow: inset 0 1px oklch(1 0 0 / 0.55);
  color: var(--ink-soft);
}

.gummy-blockquote::before {
  position: absolute;
  inset-block: 10px;
  inset-inline-start: 8px;
  width: 7px;
  border-radius: 55% 45% 48% 52%;
  background: linear-gradient(var(--fruit-grape-light), var(--fruit-grape-core), var(--fruit-grape-depth));
  box-shadow: inset 2px 0 3px oklch(1 0 0 / 0.4);
  content: "";
}

.gummy-blockquote__pool {
  position: absolute;
  right: -11px;
  bottom: -15px;
  width: 54px;
  height: 38px;
  border-radius: 60% 40% 48% 52%;
  background: color-mix(in oklch, var(--fruit-grape-core) 32%, transparent);
  filter: blur(1px);
  pointer-events: none;
}

.gummy-blockquote footer {
  margin-top: 12px;
  color: var(--muted);
  font-size: 0.83rem;
  font-weight: 650;
}

.gummy-kbd {
  display: inline-grid;
  min-width: 2em;
  min-height: 2em;
  place-items: center;
  padding: 0.28em 0.58em 0.36em;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 42%, var(--line));
  border-radius: 8px 11px 9px 10px;
  background:
    radial-gradient(ellipse at 28% 18%, oklch(1 0 0 / 0.72), transparent 24%),
    color-mix(in oklch, var(--fruit-grape-light) 22%, var(--surface-solid));
  box-shadow:
    inset 0 -3px 4px color-mix(in oklch, var(--fruit-grape-core) 16%, transparent),
    0 2px 0 color-mix(in oklch, var(--fruit-grape-depth) 32%, var(--line));
  color: var(--ink);
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.78em;
  font-weight: 720;
  line-height: 1;
  white-space: nowrap;
}

.gummy-kbd-group {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.gummy-kbd-group__separator {
  color: var(--muted);
  font-size: 0.75em;
}

.gummy-spinner {
  --spinner-size: 28px;
  --spinner-core: var(--fruit-raspberry-core);
  --spinner-rim: var(--fruit-raspberry-rim);
  display: inline-grid;
  width: var(--spinner-size);
  height: var(--spinner-size);
  flex: none;
  place-items: center;
}

.gummy-spinner[data-size="small"] { --spinner-size: 18px; }
.gummy-spinner[data-size="large"] { --spinner-size: 42px; }
.gummy-spinner[data-tone="grape"] { --spinner-core: var(--fruit-grape-core); --spinner-rim: var(--fruit-grape-rim); }
.gummy-spinner[data-tone="aqua"] { --spinner-core: var(--fruit-aqua-core); --spinner-rim: var(--fruit-aqua-rim); }
.gummy-spinner[data-tone="current"] { --spinner-core: currentColor; --spinner-rim: currentColor; }

.gummy-spinner__track {
  position: relative;
  width: 100%;
  height: 100%;
  border: max(2px, calc(var(--spinner-size) * 0.12)) solid color-mix(in oklch, var(--spinner-core) 20%, transparent);
  border-top-color: var(--spinner-rim);
  border-right-color: color-mix(in oklch, var(--spinner-core) 72%, transparent);
  border-radius: 46% 54% 48% 52%;
  animation: gummy-spinner-turn 720ms cubic-bezier(0.5, 0.05, 0.35, 0.95) infinite;
  box-shadow: inset 1px 1px 2px oklch(1 0 0 / 0.46);
}

.gummy-spinner__drop {
  position: absolute;
  top: calc(var(--spinner-size) * -0.09);
  left: 58%;
  width: calc(var(--spinner-size) * 0.25);
  height: calc(var(--spinner-size) * 0.25);
  border-radius: 60% 40% 52% 48%;
  background: var(--spinner-core);
  box-shadow: inset 1px 1px 2px oklch(1 0 0 / 0.55);
}

@keyframes gummy-spinner-turn {
  to { transform: rotate(360deg); }
}

.gummy-skeleton {
  --skeleton-base: color-mix(in oklch, var(--fruit-grape-light) 12%, var(--surface-solid));
  --skeleton-tide: color-mix(in oklch, var(--fruit-aqua-light) 34%, var(--surface-solid));
  display: block;
  width: 100%;
  overflow: hidden;
}

.gummy-skeleton__body,
.gummy-skeleton__line {
  position: relative;
  display: block;
  overflow: hidden;
  background: var(--skeleton-base);
}

.gummy-skeleton__body::after,
.gummy-skeleton__line::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 18%, var(--skeleton-tide) 48%, transparent 78%);
  content: "";
  transform: translateX(-100%);
  animation: gummy-skeleton-tide 1.6s ease-in-out infinite;
}

.gummy-skeleton[data-shape="line"] .gummy-skeleton__body {
  height: 14px;
  border-radius: 7px 10px 8px 9px;
}

.gummy-skeleton[data-shape="circle"] {
  width: 52px;
  aspect-ratio: 1;
  border-radius: 48% 52% 46% 54%;
}

.gummy-skeleton[data-shape="circle"] .gummy-skeleton__body,
.gummy-skeleton[data-shape="card"] .gummy-skeleton__body {
  width: 100%;
  height: 100%;
}

.gummy-skeleton[data-shape="card"] {
  min-height: 180px;
  border-radius: 22px 28px 24px 26px;
}

.gummy-skeleton[data-shape="text"] {
  display: grid;
  gap: 10px;
}

.gummy-skeleton__line {
  width: 100%;
  height: 12px;
  border-radius: 7px 9px 6px 8px;
}

.gummy-skeleton__line:last-child { width: 68%; }

.gummy-skeleton-group {
  display: grid;
  gap: 14px;
}

@keyframes gummy-skeleton-tide {
  60%, 100% { transform: translateX(100%); }
}

.gummy-aspect-ratio {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: 20px 28px 22px 25px;
  background: color-mix(in oklch, var(--fruit-aqua-light) 22%, var(--surface-solid));
}

.gummy-aspect-ratio::after {
  position: absolute;
  right: -16px;
  bottom: -18px;
  width: 82px;
  height: 58px;
  border: 1px solid color-mix(in oklch, var(--fruit-aqua-rim) 38%, transparent);
  border-radius: 58% 42% 48% 52%;
  background:
    radial-gradient(circle at 28% 18%, oklch(1 0 0 / 0.62), transparent 20%),
    color-mix(in oklch, var(--fruit-aqua-core) 30%, transparent);
  content: "";
  pointer-events: none;
}

.gummy-aspect-ratio__content {
  position: absolute;
  inset: 0;
}

.gummy-aspect-ratio[data-fit="cover"] :is(img, video) { width: 100%; height: 100%; object-fit: cover; }
.gummy-aspect-ratio[data-fit="contain"] :is(img, video) { width: 100%; height: 100%; object-fit: contain; }
.gummy-aspect-ratio[data-fit="fill"] :is(img, video) { width: 100%; height: 100%; object-fit: fill; }

@media (prefers-reduced-motion: reduce) {
  .gummy-spinner__track {
    animation: none;
    border-style: dotted;
  }

  .gummy-skeleton__body::after,
  .gummy-skeleton__line::after {
    animation: none;
    opacity: 0.5;
    transform: none;
  }
}

.gummy-combobox,
.gummy-date-picker {
  display: grid;
  gap: 7px;
}

.gummy-combobox__label,
.gummy-date-picker__label {
  color: var(--ink);
  font-size: 13px;
  font-weight: 690;
}

.gummy-combobox__input-group {
  display: grid;
  min-height: 48px;
  grid-template-columns: minmax(0, 1fr) 44px;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 34%, var(--line));
  border-radius: 14px 20px 16px 18px;
  background: var(--surface-solid);
}

.gummy-combobox__input {
  min-width: 0;
  padding: 10px 14px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
}

.gummy-combobox__trigger {
  border: 0;
  border-inline-start: 1px solid var(--line);
  background: color-mix(in oklch, var(--fruit-grape-light) 18%, transparent);
  color: var(--ink);
  cursor: pointer;
}

.gummy-combobox__input-group:focus-within {
  border-color: var(--fruit-aqua-rim);
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-combobox__popup,
.gummy-select__popup {
  width: var(--anchor-width);
  min-width: 220px;
  max-height: min(320px, var(--available-height));
  padding: 7px;
  overflow: auto;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 38%, var(--line));
  border-radius: 15px 21px 17px 19px;
  outline: none;
  background: var(--surface-solid);
  box-shadow: 0 18px 54px color-mix(in oklch, var(--ink) 18%, transparent);
  transform-origin: var(--transform-origin);
  transition: opacity 130ms ease, transform 130ms ease;
}

.gummy-combobox__popup[data-starting-style],
.gummy-combobox__popup[data-ending-style],
.gummy-select__popup[data-starting-style],
.gummy-select__popup[data-ending-style] {
  opacity: 0;
  transform: scale(0.97);
}

.gummy-combobox__item,
.gummy-select__item {
  display: grid;
  min-height: 40px;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
  border-radius: 10px 14px 11px 13px;
  color: var(--ink-soft);
  font-size: 13px;
  cursor: default;
  user-select: none;
}

.gummy-combobox__item[data-highlighted],
.gummy-select__item[data-highlighted] {
  background: color-mix(in oklch, var(--fruit-aqua-light) 18%, var(--surface-solid));
  color: var(--ink);
}

.gummy-combobox__item[data-selected],
.gummy-select__item[data-selected] {
  background:
    radial-gradient(ellipse at 96% 100%, color-mix(in oklch, var(--fruit-grape-core) 25%, transparent), transparent 38%),
    color-mix(in oklch, var(--fruit-grape-light) 16%, var(--surface-solid));
}

.gummy-combobox__indicator,
.gummy-select__indicator {
  color: var(--fruit-grape-depth);
  font-weight: 800;
}

.gummy-combobox__empty,
.gummy-command__empty {
  padding: 18px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}

.gummy-select__trigger {
  display: grid;
  min-width: 220px;
  min-height: 48px;
  grid-template-columns: minmax(0, 1fr) 34px;
  align-items: center;
  padding: 8px 8px 8px 14px;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 34%, var(--line));
  border-radius: 14px 20px 16px 18px;
  background: var(--surface-solid);
  color: var(--ink);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.gummy-select__trigger:focus-visible {
  outline: none;
  border-color: var(--fruit-aqua-rim);
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-select__icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 46% 54% 48% 52%;
  background: color-mix(in oklch, var(--fruit-grape-core) 28%, transparent);
}

.gummy-select__scroll-arrow {
  position: sticky;
  z-index: 1;
  display: grid;
  height: 28px;
  place-items: center;
  background: var(--surface-solid);
  color: var(--muted);
}

.gummy-input-group {
  display: grid;
  min-height: 48px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 32%, var(--line));
  border-radius: 14px 20px 16px 18px;
  background: var(--surface-solid);
}

.gummy-input-group:focus-within {
  border-color: var(--fruit-aqua-rim);
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-input-group__addon,
.gummy-input-group__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 12px;
  border: 0;
  background: color-mix(in oklch, var(--fruit-grape-light) 14%, transparent);
  color: var(--ink-soft);
  font-size: 12px;
}

.gummy-input-group__addon[data-position="start"],
.gummy-input-group__button:first-child {
  border-inline-end: 1px solid var(--line);
}

.gummy-input-group__addon[data-position="end"],
.gummy-input-group__button:last-child {
  border-inline-start: 1px solid var(--line);
}

.gummy-input-group__button {
  min-width: 44px;
  color: var(--ink);
  font-weight: 700;
  cursor: pointer;
}

.gummy-input-group__button:focus-visible {
  outline: none;
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-input-group__control {
  min-width: 0;
  padding: 9px 12px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
}

.gummy-calendar {
  display: grid;
  width: min(100%, 350px);
  gap: 12px;
  padding: 14px;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 28%, var(--line));
  border-radius: 20px 27px 22px 24px;
  background: var(--surface-solid);
}

.gummy-calendar__header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 7px;
}

.gummy-calendar__header strong {
  text-align: center;
  font-family: var(--font-display), sans-serif;
  letter-spacing: -0.025em;
}

.gummy-calendar__header button,
.gummy-calendar__grid button {
  min-width: 40px;
  min-height: 40px;
  border: 1px solid transparent;
  border-radius: 11px 15px 12px 14px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.gummy-calendar__header button {
  min-width: 44px;
  min-height: 44px;
  border-color: var(--line);
  background: color-mix(in oklch, var(--fruit-grape-light) 12%, transparent);
}

.gummy-calendar__grid {
  display: grid;
  gap: 3px;
}

.gummy-calendar__grid [role="row"] {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 3px;
}

.gummy-calendar__weekdays span {
  display: grid;
  min-height: 28px;
  place-items: center;
  color: var(--muted);
  font-family: var(--font-mono), monospace;
  font-size: 9px;
  text-transform: uppercase;
}

.gummy-calendar__grid button[data-outside] {
  color: var(--muted);
  opacity: 0.55;
}

.gummy-calendar__grid button[data-today] {
  border-color: color-mix(in oklch, var(--fruit-aqua-rim) 64%, var(--line));
}

.gummy-calendar__grid button[aria-selected="true"] {
  border-color: var(--fruit-raspberry-rim);
  background:
    radial-gradient(circle at 28% 18%, oklch(1 0 0 / 0.62), transparent 20%),
    linear-gradient(145deg, var(--fruit-raspberry-light), var(--fruit-raspberry-core));
  box-shadow: inset 0 -4px 5px color-mix(in oklch, var(--fruit-raspberry-depth) 28%, transparent);
}

.gummy-calendar__grid button:focus-visible,
.gummy-calendar__header button:focus-visible {
  outline: none;
  border-color: var(--fruit-aqua-rim);
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-calendar__grid button:disabled {
  cursor: not-allowed;
  opacity: 0.28;
}

.gummy-date-picker .gummy-overlay-trigger {
  min-width: 220px;
  justify-content: space-between;
  gap: 20px;
}

.gummy-date-picker__close {
  width: 100%;
  min-height: 40px;
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: 11px 15px 12px 14px;
  background: var(--surface-solid);
  color: var(--ink);
  cursor: pointer;
}

.gummy-otp {
  display: grid;
  gap: 8px;
}

.gummy-otp__label {
  color: var(--ink);
  font-size: 13px;
  font-weight: 690;
}

.gummy-otp__slots {
  display: flex;
  max-width: 100%;
  gap: 7px;
}

.gummy-otp__slots input {
  width: 44px;
  height: 52px;
  min-width: 0;
  padding: 0;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 34%, var(--line));
  border-radius: 12px 16px 13px 15px;
  outline: 0;
  background: var(--surface-solid);
  color: var(--ink);
  font-family: var(--font-mono), monospace;
  font-size: 18px;
  font-weight: 760;
  text-align: center;
}

.gummy-otp__slots input:focus-visible {
  border-color: var(--fruit-aqua-rim);
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-otp[data-invalid="true"] .gummy-otp__slots input {
  border-color: var(--fruit-raspberry-rim);
}

.gummy-command {
  width: min(100%, 540px);
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 34%, var(--line));
  border-radius: 20px 27px 22px 24px;
  background: var(--surface-solid);
  box-shadow: 0 18px 54px color-mix(in oklch, var(--ink) 14%, transparent);
}

.gummy-command__input {
  width: 100%;
  min-height: 52px;
  padding: 12px 16px;
  border: 0;
  border-bottom: 1px solid var(--line);
  outline: 0;
  background: transparent;
  color: var(--ink);
}

.gummy-command__input:focus-visible {
  box-shadow: inset 0 -3px 0 var(--fruit-aqua-rim);
}

.gummy-command__list {
  max-height: 320px;
  padding: 7px;
  overflow: auto;
}

.gummy-command__group-label {
  padding: 9px 10px 5px;
  color: var(--muted);
  font-family: var(--font-mono), monospace;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.gummy-command__item {
  display: flex;
