.gummy-table__head {
  color: var(--muted);
  background: color-mix(in oklch, var(--fruit-grape-light) 10%, transparent);
  font-size: 11px;
  font-weight: 780;
  letter-spacing: 0.035em;
  text-transform: uppercase;
}

.gummy-table__head[data-align="center"],
.gummy-table__cell[data-align="center"] {
  text-align: center;
}

.gummy-table__head[data-align="end"],
.gummy-table__cell[data-align="end"] {
  text-align: end;
}

.gummy-table__row[data-selected] .gummy-table__cell {
  background: color-mix(in oklch, var(--fruit-aqua-light) 13%, transparent);
}

.gummy-table__body .gummy-table__row:hover .gummy-table__cell {
  background: color-mix(in oklch, var(--fruit-grape-light) 9%, transparent);
}

.gummy-table__footer {
  font-weight: 720;
}

.gummy-data-table {
  display: grid;
  width: 100%;
  gap: 12px;
}

.gummy-data-table__toolbar,
.gummy-data-table__pagination {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 10px;
}

.gummy-data-table__toolbar label {
  display: grid;
  min-width: min(100%, 16rem);
  gap: 5px;
  color: var(--ink-soft);
  font-size: 11px;
  font-weight: 720;
}

.gummy-data-table__toolbar input[type="search"] {
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid color-mix(in oklch, var(--fruit-aqua-rim) 26%, var(--line));
  border-radius: 12px 16px 13px 15px;
  outline: none;
  background: var(--surface-solid);
  color: var(--ink);
  font: inherit;
}

.gummy-data-table__toolbar input[type="search"]:focus-visible {
  border-color: color-mix(in oklch, var(--fruit-aqua-rim) 72%, var(--line));
  box-shadow: inset 0 -3px 0 color-mix(in oklch, var(--fruit-aqua-core) 44%, transparent);
}

.gummy-data-table__toolbar > span,
.gummy-data-table__pagination > span {
  color: var(--muted);
  font-family: var(--font-mono), monospace;
  font-size: 10px;
}

.gummy-data-table__selection {
  width: 48px;
  min-width: 48px;
  text-align: center;
}

.gummy-data-table input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--fruit-grape-rim);
}

.gummy-data-table__selection input:focus-visible {
  outline: 2px solid var(--fruit-aqua-rim);
  outline-offset: 3px;
}

.gummy-data-table__empty {
  padding-block: 32px;
  color: var(--muted);
  text-align: center;
}

.gummy-table__head button,
.gummy-data-table__pagination button {
  min-height: 36px;
  padding: 0 10px;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 28%, var(--line));
  border-radius: 10px 14px 11px 13px;
  background: color-mix(in oklch, var(--fruit-grape-light) 12%, var(--surface-solid));
  color: var(--ink);
  font: inherit;
  font-weight: 720;
}

.gummy-table__head button {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  gap: 7px;
  padding-inline: 7px;
  border-color: transparent;
  background: transparent;
  color: inherit;
  text-transform: inherit;
}

.gummy-table__head button:focus-visible,
.gummy-data-table__pagination button:focus-visible {
  outline: 2px solid var(--fruit-aqua-rim);
  outline-offset: 2px;
}

.gummy-data-table__pagination > div {
  display: flex;
  gap: 8px;
}

.gummy-data-table__pagination button:disabled {
  opacity: 0.48;
}

.gummy-carousel {
  --gummy-carousel-direction: -1;
  position: relative;
  display: grid;
  min-width: 0;
  gap: 12px;
}

.gummy-carousel[dir="rtl"] {
  --gummy-carousel-direction: 1;
}

.gummy-carousel__viewport {
  display: flex;
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 27%, var(--line));
  border-radius: 22px 29px 24px 27px;
  outline: none;
  background: color-mix(in oklch, var(--surface-solid) 90%, var(--fruit-grape-light));
  box-shadow: inset 0 1px oklch(1 0 0 / 0.48);
}

.gummy-carousel__viewport:focus-visible {
  border-color: color-mix(in oklch, var(--fruit-aqua-rim) 72%, var(--line));
  box-shadow: inset 0 -4px 0 color-mix(in oklch, var(--fruit-aqua-core) 44%, transparent);
}

.gummy-carousel__item {
  min-width: 100%;
  flex: 0 0 100%;
  padding: clamp(20px, 6vw, 44px);
  transform: translateX(calc(var(--gummy-carousel-index) * var(--gummy-carousel-direction) * 100%));
  transition: transform 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.gummy-carousel[data-orientation="vertical"] .gummy-carousel__viewport {
  display: grid;
  max-height: 18rem;
}

.gummy-carousel[data-orientation="vertical"] .gummy-carousel__item {
  grid-area: 1 / 1;
  transform: translateY(calc(var(--gummy-carousel-index) * -100%));
}

.gummy-carousel__control {
  display: inline-grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid color-mix(in oklch, var(--fruit-aqua-rim) 34%, var(--line));
  border-radius: 46% 54% 48% 52%;
  background:
    radial-gradient(circle at 28% 18%, oklch(1 0 0 / 0.68), transparent 20%),
    color-mix(in oklch, var(--fruit-aqua-light) 28%, var(--surface-solid));
  color: var(--ink);
  font: inherit;
  font-size: 18px;
}

.gummy-carousel__control:focus-visible {
  outline: 2px solid var(--fruit-aqua-rim);
  outline-offset: 3px;
}

.gummy-carousel__control:disabled {
  opacity: 0.42;
}

.gummy-carousel__indicators {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.gummy-carousel__indicators button {
  width: 11px;
  height: 11px;
  padding: 0;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 36%, var(--line));
  border-radius: 50%;
  background: color-mix(in oklch, var(--fruit-grape-light) 22%, var(--surface-solid));
}

.gummy-carousel__indicators button[aria-current] {
  width: 24px;
  border-radius: 9px 12px 10px 11px;
  background: var(--fruit-grape-core);
}

.gummy-carousel__indicators button:focus-visible {
  outline: 2px solid var(--fruit-aqua-rim);
  outline-offset: 3px;
}

.gummy-carousel-demo__controls {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.gummy-resizable {
  display: grid;
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 25%, var(--line));
  border-radius: 20px 26px 22px 24px;
  background: var(--surface-solid);
}

.gummy-resizable[data-orientation="horizontal"] {
  grid-template-columns: minmax(0, var(--gummy-resizable-size)) 10px minmax(0, 1fr);
}

.gummy-resizable[data-orientation="vertical"] {
  min-height: 18rem;
  grid-template-rows: minmax(0, var(--gummy-resizable-size)) 10px minmax(0, 1fr);
}

.gummy-resizable__panel {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  padding: 16px;
}

.gummy-resizable__handle {
  display: grid;
  min-width: 10px;
  min-height: 10px;
  place-items: center;
  outline: none;
  background: color-mix(in oklch, var(--fruit-grape-core) 18%, var(--line));
  color: var(--ink-soft);
  cursor: col-resize;
  touch-action: none;
}

.gummy-resizable__handle[data-orientation="vertical"] {
  cursor: row-resize;
}

.gummy-resizable__handle > span {
  display: grid;
  width: 18px;
  height: 28px;
  place-items: center;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 42%, var(--line));
  border-radius: 8px 11px 9px 10px;
  background: var(--surface-solid);
  font-size: 14px;
  line-height: 1;
}

.gummy-resizable__handle[data-orientation="vertical"] > span {
  width: 28px;
  height: 18px;
  transform: rotate(90deg);
}

.gummy-resizable__handle:focus-visible {
  background: color-mix(in oklch, var(--fruit-aqua-core) 45%, var(--line));
}

.gummy-scroll-area {
  position: relative;
  width: 100%;
  min-height: 10rem;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 24%, var(--line));
  border-radius: 18px 24px 20px 22px;
  background: color-mix(in oklch, var(--surface-solid) 94%, var(--fruit-grape-light));
}

.gummy-scroll-area__viewport {
  width: 100%;
  height: 100%;
  outline: none;
}

.gummy-scroll-area__viewport:focus-visible {
  box-shadow: inset 0 0 0 2px var(--fruit-aqua-rim);
}

.gummy-scroll-area__content {
  min-width: 100%;
  padding: 14px 22px 14px 14px;
}

[dir="rtl"] .gummy-scroll-area__content {
  padding-right: 14px;
  padding-left: 22px;
}

.gummy-scroll-area__scrollbar {
  display: flex;
  width: 14px;
  justify-content: center;
  padding: 2px;
  background: color-mix(in oklch, var(--fruit-grape-light) 16%, transparent);
  opacity: 0;
  transition: opacity 160ms ease;
  pointer-events: none;
}

.gummy-scroll-area__scrollbar[data-orientation="horizontal"] {
  width: auto;
  height: 14px;
}

.gummy-scroll-area__scrollbar[data-hovering],
.gummy-scroll-area__scrollbar[data-scrolling] {
  opacity: 1;
  pointer-events: auto;
}

.gummy-scroll-area__thumb {
  width: 100%;
  min-height: 34px;
  border-radius: 7px 10px 8px 9px;
  background:
    linear-gradient(oklch(1 0 0 / 0.35), transparent 44%),
    color-mix(in oklch, var(--fruit-grape-core) 62%, var(--line));
}

.gummy-scroll-area__scrollbar[data-orientation="horizontal"] .gummy-scroll-area__thumb {
  min-width: 34px;
  min-height: 0;
  height: 100%;
}

.gummy-toaster {
  position: fixed;
  z-index: 100;
  display: flex;
  width: min(23rem, calc(100vw - 2rem));
  max-height: calc(100vh - 2rem);
  flex-direction: column;
  gap: 10px;
  margin: 1rem;
  outline: none;
}

.gummy-toaster[data-position^="top"] { top: 0; }
.gummy-toaster[data-position^="bottom"] { bottom: 0; }
.gummy-toaster[data-position$="left"] { left: 0; }
.gummy-toaster[data-position$="right"] { right: 0; }

.gummy-toast {
  --toast-swipe-movement-x: 0px;
  --toast-swipe-movement-y: 0px;
  position: relative;
  width: 100%;
  overflow: hidden;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 34%, var(--line));
  border-radius: 18px 24px 20px 22px;
  background:
    radial-gradient(ellipse at 0 100%, color-mix(in oklch, var(--fruit-grape-core) 18%, transparent), transparent 32%),
    color-mix(in oklch, var(--surface-solid) 96%, var(--fruit-grape-light));
  box-shadow: 0 16px 38px oklch(0.16 0.035 310 / 0.18), inset 0 1px oklch(1 0 0 / 0.58);
  color: var(--ink);
  transform: translateX(var(--toast-swipe-movement-x)) translateY(var(--toast-swipe-movement-y));
  transition: transform 280ms cubic-bezier(0.22, 1, 0.36, 1), opacity 180ms ease;
}

.gummy-toast[data-type="success"] { border-color: color-mix(in oklch, var(--fruit-lime-rim) 48%, var(--line)); }
.gummy-toast[data-type="error"] { border-color: color-mix(in oklch, var(--fruit-raspberry-rim) 52%, var(--line)); }
.gummy-toast[data-type="warning"] { border-color: color-mix(in oklch, var(--fruit-tangerine-rim) 48%, var(--line)); }

.gummy-toast[data-starting-style],
.gummy-toast[data-ending-style] {
  opacity: 0;
  transform: translateY(22px);
}

.gummy-toast[data-ending-style][data-swipe-direction="right"] {
  transform: translateX(calc(var(--toast-swipe-movement-x) + 120%));
}

.gummy-toast[data-ending-style][data-swipe-direction="left"] {
  transform: translateX(calc(var(--toast-swipe-movement-x) - 120%));
}

.gummy-toast__content {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 11px;
  padding: 12px;
}

.gummy-toast__reservoir {
  width: 12px;
  height: 28px;
  border-radius: 48% 52% 45% 55%;
  background: linear-gradient(var(--fruit-grape-light), var(--fruit-grape-core));
  box-shadow: inset 0 -4px 4px color-mix(in oklch, var(--fruit-grape-rim) 32%, transparent);
}

.gummy-toast[data-type="success"] .gummy-toast__reservoir { background: linear-gradient(var(--fruit-lime-light), var(--fruit-lime-core)); }
.gummy-toast[data-type="error"] .gummy-toast__reservoir { background: linear-gradient(var(--fruit-raspberry-light), var(--fruit-raspberry-core)); }
.gummy-toast[data-type="warning"] .gummy-toast__reservoir { background: linear-gradient(var(--fruit-tangerine-light), var(--fruit-tangerine-core)); }

.gummy-toast__copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.gummy-toast__title {
  font-size: 13px;
  font-weight: 780;
}

.gummy-toast__description {
  color: var(--ink-soft);
  font-size: 12px;
  line-height: 1.4;
}

.gummy-toast__action,
.gummy-toast__close {
  min-height: 36px;
  border: 1px solid color-mix(in oklch, var(--fruit-grape-rim) 30%, var(--line));
  border-radius: 10px 14px 11px 13px;
  background: var(--surface-solid);
  color: var(--ink);
  font: inherit;
  font-size: 12px;
  font-weight: 720;
}

.gummy-toast__close {
  width: 36px;
  padding: 0;
  font-size: 20px;
}

.gummy-toast__action:focus-visible,
.gummy-toast__close:focus-visible {
  outline: 2px solid var(--fruit-aqua-rim);
  outline-offset: 2px;
}

@media (max-width: 640px) {
  .gummy-data-table__toolbar {
    align-items: stretch;
  }

  .gummy-data-table__toolbar label {
    width: 100%;
  }

  .gummy-toast__content {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .gummy-toast__action {
    grid-column: 2 / -1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gummy-carousel__item,
  .gummy-scroll-area__scrollbar,
  .gummy-toast {
    transition: none;
  }
}
